package com.careerpilot.modules.jobmatch.scoring;
import com.careerpilot.modules.jobmatch.entity.AlignmentStatus;import com.careerpilot.modules.profile.entity.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class AlignmentService{public Alignment experience(String jd,Profile profile,String resume){String lower=jd.toLowerCase(Locale.ROOT);if(lower.matches(".*\\b(fresher|entry[ -]level|intern(ship)?)\\b.*")){boolean entry=profile!=null&&(profile.getExperienceLevel()==ExperienceLevel.STUDENT||profile.getExperienceLevel()==ExperienceLevel.ENTRY_LEVEL||profile.getExperienceLevel()==ExperienceLevel.JUNIOR);return new Alignment(entry?100:70,entry?AlignmentStatus.MATCHED:AlignmentStatus.PARTIAL);}var matcher=java.util.regex.Pattern.compile("(\\d+)\\s*(?:-|to|–)\\s*(\\d+)\\s*years?|(?:at least\\s*)?(\\d+)\\+?\\s*years?").matcher(lower);if(!matcher.find())return new Alignment(null,AlignmentStatus.NOT_REQUIRED);int required=Integer.parseInt(matcher.group(1)!=null?matcher.group(1):matcher.group(3));Integer estimated=estimate(profile);if(estimated==null)return new Alignment(null,AlignmentStatus.UNKNOWN);return estimated>=required?new Alignment(100,AlignmentStatus.MATCHED):estimated+1>=required?new Alignment(60,AlignmentStatus.PARTIAL):new Alignment(20,AlignmentStatus.NOT_MATCHED);}
 public Alignment education(String jd,Profile profile,String resume){String lower=jd.toLowerCase(Locale.ROOT);boolean required=lower.matches(".*\\b(b\\.?tech|b\\.?e\\.?|bca|mca|b\\.?sc|m\\.?tech|computer science|related degree|bachelor'?s|master'?s)\\b.*");if(!required)return new Alignment(null,AlignmentStatus.NOT_REQUIRED);String candidate=((profile==null?"":String.valueOf(profile.getDegree()))+" "+resume).toLowerCase(Locale.ROOT);boolean matches=candidate.matches("(?s).*\\b(b\\.?tech|b\\.?e\\.?|bca|mca|b\\.?sc|m\\.?tech|computer science|bachelor|master)\\b.*");return matches?new Alignment(100,AlignmentStatus.MATCHED):new Alignment(null,AlignmentStatus.UNKNOWN);}
 private Integer estimate(Profile profile){if(profile==null||profile.getExperienceLevel()==null)return null;return switch(profile.getExperienceLevel()){case STUDENT->0;case ENTRY_LEVEL->1;case JUNIOR->2;case MID_LEVEL->4;case SENIOR->7;};}public record Alignment(Integer score,AlignmentStatus status){}}
